  'settings.rules.var.match': 'Grup tangkapan N dari pola «cocok dengan pola» aturan ini pada ruas FIELD. Inilah <jd:source:N> milik JDownloader, dengan nama yang menyatakan pola mana yang dibacanya. Aturan tanpa pola yang cocok pada ruas itu ditolak saat disimpan, alih-alih diam-diam menghasilkan folder bernama <jd:match:url:1>.',
