  'settings.reconnect.offState': 'Sambung ulang sedang mati. Tidak ada yang meminta alamat baru ke router, dan batas hoster diserahkan pada jeda coba lagi yang biasa.',

  'settings.reconnect.command': 'Program',
  'settings.reconnect.commandHint': 'Jalur lengkap program yang akan dijalankan. Program dijalankan langsung, bukan lewat shell, jadi pipa, pengalihan, atau dua perintah berurutan tempatnya di cara “Skrip”. %%router%%, %%username%%, %%password%%, dan %%ip%% diisikan sebelum program mulai.',
  'settings.reconnect.args': 'Argumen',
