  'settings.reconnect.upnpState': 'Tidak perlu apa-apa lagi. Gateway ditemukan dengan bertanya ke jaringan, jadi inilah cara yang bekerja tanpa perlu tahu apa pun tentang router.',
  'settings.reconnect.upnpLocation': 'URL deskripsi gateway',
  'settings.reconnect.upnpLocationHint': 'Opsional, dan biasanya dibiarkan kosong. Isi hanya di tempat pencarian multicast disaring padahal gateway-nya sendiri terjangkau dengan baik, keadaan yang tidak akan pernah bisa diperbaiki oleh penemuan otomatis saja.',

  'settings.reconnect.interpreter': 'Penafsir',
  'settings.reconnect.interpreterHint': 'Program yang menerima skrip, dengan jalur lengkapnya: /bin/sh, /bin/bash, /usr/bin/python3.',
  'settings.reconnect.interpreterArgs': 'Argumen penafsir',
  'settings.reconnect.interpreterArgsHint': 'Satu per baris, diletakkan sebelum berkas skrip. Biasanya kosong.',
  'settings.reconnect.script': 'Skrip',
  'settings.reconnect.scriptHint': 'Isinya ditulis ke berkas sementara yang privat, dan penafsir hanya diberi jalurnya, jadi tidak ada apa pun dari sini yang berakhir dalam tanda kutip di baris perintah. Variabel diisikan sebelum berkas ditulis, artinya kata sandi yang kamu ketik di kotak ini ikut sampai ke berkas itu: dengan %%password%% ia tetap di bidang kata sandi.',

  'settings.reconnect.router': 'Alamat router',
  'settings.reconnect.routerHint': 'Router di jaringanmu sendiri, tanpa skema: 192.168.1.1, bukan http://192.168.1.1/. Itulah yang menjadi isi %%router%%. Ini bukan alamat publik, dan keduanya jangan pernah tertukar: permintaan login yang diarahkan ke alamat publik mengirim kata sandi router-mu ke internet.',
  'settings.reconnect.routerFind': 'Cari router saya',
