  'settings.reconnect.checkTitle': 'Memeriksa alamat',
  'settings.reconnect.checkUrl': 'URL pemeriksaan IP',
  'settings.reconnect.checkUrlHint': 'Diambil sebelum cara itu dijalankan dan sekali lagi sesudahnya; jalannya dianggap selesai begitu alamat yang ditampilkannya berubah. Tidak ada nilai bawaan: pengelola unduhan yang kamu jalankan sendiri tidak seharusnya mulai melaporkan alamatmu ke layanan yang tidak pernah kamu pilih. Yang ditampilkan harus alamat yang dilihat internet, sebab halaman yang mengembalikan alamat di jaringanmu sendiri tidak bisa membedakan sambung ulang dari jalan yang tidak mengubah apa-apa.',
  'settings.reconnect.checkPresets': 'Layanan yang dikenal',
  'settings.reconnect.checkPresetsHint': 'Jalan pintas bagi yang tidak punya pilihan tertentu, bukan nilai bawaan: tidak ada satu pun yang dipilihkan untukmu, dan halaman apa pun yang menampilkan alamat publikmu sama bagusnya.',
  'settings.reconnect.interval': 'Detik antar pemeriksaan (1 sampai 60)',
  'settings.reconnect.intervalHint': 'Berapa lama menunggu di antara dua kali melihat URL pemeriksaan setelah cara itu dijalankan. Ada batas bawah, karena perulangan tanpa batas bawah menjadikan layanan pemeriksa sebagai sasaran.',
  'settings.reconnect.timeout': 'Detik untuk terus memeriksa (5 sampai 900)',
  'settings.reconnect.timeoutHint': 'How long to keep looking before the run is called a failure. A reconnect still waiting a quarter of an hour later has failed whatever this says. A timeout below the interval is raised to it, or the run would be over before a single check happened. The Command and Script methods give their program the same number of seconds to finish before the checking starts; one still running then is stopped, and the run fails.',
