  'settings.chunksHint': 'Berapa koneksi yang dibuka satu unduhan bila tidak ada yang lebih khusus berlaku. Sebuah aturan, atau satu unduhan, bisa menyebut angkanya sendiri dan mengalahkan yang ini. Host yang hanya tahan lebih sedikit tetap dapat lebih sedikit: batas host hanya bisa menurunkan angkanya, tidak pernah menaikkan. Dengan 0 aplikasi yang memutuskan. Lebih dari segelintir koneksi tidak menghasilkan apa-apa di host yang membatasi per berkas, dan merupakan cara pasti agar sebuah akun ditandai.',
