  'settings.access.relay.title': 'Relai proyek',
  'settings.access.relay.body': 'Relay adalah perantara yang membuat semua instansimu bisa dijangkau dari luar jaringan rumah, jadi dari mana saja. Yang ini disediakan gratis oleh proyek.',
  'settings.access.relay.use': 'Pakai relai proyek',
  'settings.access.relay.leadProject': 'Jalan tanpa disetel apa pun. Semua yang dikatakan instansmu satu sama lain terenkripsi, dan kuncinya hanya kamu yang punya.',
  'settings.access.relay.seesButton': 'Apa yang dilihatnya?',
  'settings.access.relay.seesTip': 'Tidak terlihat oleh relay: tautanmu, unduhanmu, berkasmu, dan token aksesmu.\n\nTerlihat oleh relay: alamat IP instansimu dan kapan mereka mengirim sesuatu.\n\nItu tidak bisa disembunyikan dengan enkripsi. Kalau mengganggumu, jalankan relay sendiri.',
