  'settings.access.ownRelay.containerLabel': 'Sebagai kontainer sendiri',
  'settings.access.ownRelay.containerHint': 'Kalau tidak ada instansimu yang bisa dijangkau dari luar, relay harus berada di tempat lain: di servermu atau VPS kecil. Pasang kontainer dari Unraid Community Applications, atau dengan perintah di bawah.\n\nKontainer tidak perlu disetel: jalankan, isi alamatnya di atas, selesai. Ia tidak menyimpan apa pun, jadi tidak ada yang perlu dicadangkan.',
  'settings.access.tokens.title': 'Token API',
