  'settings.access.identity.title': 'Identitas instans ini',
  'settings.access.identity.nameLabel': 'Nama',
  'settings.access.identity.namePlaceholder': 'mis. Server rumah',
  'settings.access.identity.nameHint': 'Ditawarkan lebih dulu saat pemasangan dan pada kode QR di bawah, alih-alih nama apa pun yang kebetulan diberikan sistem operasi atau runtime kontainer untuk mesin ini. Opsional: biarkan kosong untuk tetap memakai nama itu.',
  'settings.access.identity.domainsLabel': 'Domain yang diketahui',
  'settings.access.identity.domainsHint': 'Setiap domain diingat otomatis saat permintaan pertama datang lewat domain itu, dan tetap tercantum di sini walaupun permintaan berikutnya datang lewat IP LAN. Tambahkan domain secara manual kalau domain itu sudah dikonfigurasi tapi belum ada permintaan yang masuk lewatnya. Satu alamat lengkap per baris, mis. https://kl.example.com.',
  'settings.access.cardTitle': 'Menghubungkan instans dan akses jarak jauh',
  'settings.access.phrase.body': 'Satu frasa menghubungkan semua KnightLoader yang kamu jalankan. Buat di sini, lalu tempel ke instans lainnya. Kamu tidak butuh akun atau login, dan tidak ada yang perlu diatur.',
  'settings.access.phrase.noPasswordWarning': 'Instance ini tidak punya kata sandi. Frasa ini menjangkau setiap instance yang Anda hubungkan dengannya, jadi siapa pun yang bisa membacanya di sini menjangkau semuanya, bukan hanya yang ini. Sebaiknya atur kata sandi di atas dulu.',
  'settings.access.phrase.activate': 'Buat frasa',
  'settings.access.phrase.howStep1': 'Di instans ini, tekan "{button}". Muncul dua belas kata.',
  'settings.access.phrase.howStep2': 'Buka KnightLoader di mesin satunya, masuk ke halaman yang sama ini, tekan "{button}" lalu ketik dua belas katanya.',
  'settings.access.phrase.howStep3': 'Selesai! Setiap instansi kini muncul pada yang lain di bawah “Instansi”, dan kamu bisa mengendalikan salah satunya dari mana pun. Dengan relay menyala, instansimu terjangkau dari luar jaringanmu.',
  'settings.access.phrase.howWhat': 'Kata-kata itu rahasia, bukan alamat. Tiap instansi menghitung dua kunci darinya: satu untuk menemukan yang lain, satu untuk mengenkripsi.\n\nUntuk saling menemukan, tiap instansi sendiri menghubungi titik temu yang sama di internet. Yang menunjukkan kunci sama akan disambungkan. Karena itu tidak ada instansimu yang harus bisa dijangkau dari luar.\n\nTitik temu tidak bisa ikut membaca. Ia tak pernah melihat kata-katamu, dan semua yang lewat di sana terenkripsi dengan kunci kedua.',
  'settings.access.phrase.statusDisconnected': 'Tidak terhubung',
  'settings.access.phrase.statusHintProject': 'Terhubung ke relay proyek. Akses jarak jauh sudah siap.',
  'settings.access.phrase.statusHintOwn': 'Terhubung ke relay milikmu. Akses jarak jauh sudah siap.',
  'settings.access.phrase.statusHintOff': 'Tidak ada relay aktif. Instansimu hanya bisa dijangkau di jaringan lokal.',
  'settings.access.phrase.statusHintLost': 'Tidak ada kontak dengan relay. KnightLoader terus mencoba. Sampai itu instansimu hanya saling menjangkau di jaringan lokal.',
  'settings.access.phrase.statusConnected': 'Terhubung',
