  'settings.resolvers.about': 'Konfigurasi untuk backend yt-dlp, yang mengambil dari situs media dan streaming yang didukung yt-dlp sendiri. Layanan mana yang menangani sebuah tautan (yt-dlp, akun debrid, atau backend JDownloader) ditentukan oleh urutan prioritas di halaman Akun. Halaman ini mengatur apa yang dilakukan yt-dlp setelah sebuah tautan diarahkan kepadanya.',
