  'settings.torrents.portMapUnconfirmed': 'Router menerima permintaannya, tapi pemetaannya tidak bisa dipastikan berfungsi. Beberapa router menerima permintaan diam-diam tanpa menerapkannya. Coba periksa konektivitas dari luar jaringan.',
  'settings.torrents.portMapFailed': 'Tidak dapat memetakan port: {error}',
