  'settings.torrents.pex': 'Pertukaran peer (PEX)',
  'settings.torrents.pexHint': 'Menukar peer yang diketahui dengan yang sudah terhubung, sehingga swarm dengan sedikit peer ditemukan lebih cepat.',
  'settings.torrents.privateNote': 'Torrent privat otomatis mematikan keduanya begitu metadatanya diketahui, apa pun pengaturan di sini: langsung untuk berkas .torrent yang diunggah, atau segera setelah metadata tautan magnet itu sendiri tiba dari swarm. Sebagian besar tracker privat memblokir akun yang memakai salah satunya.',
  'container.noJD': 'berkas ini terenkripsi, dan hanya backend JDownloader yang bisa membukanya. Belum ada yang disiapkan: setel KL_JD ke JDownloader yang bisa dijangkau instans ini, lalu mulai ulang.',
  'container.jdOff': 'berkas ini terenkripsi, dan hanya backend JDownloader yang bisa membukanya. “Backend JDownloader” dimatikan di halaman Modul.',
  'torrent.staging': 'Menambahkan…',
  'torrent.staged': '{file} ditambahkan ke pengumpul.',
  'torrent.stagedIn': '{file} ditambahkan ke pengumpul di “{pkg}”.',
  'torrent.duplicate': '{file} sudah ada di daftar.',
  'torrent.onlyOne': 'hanya satu .torrent yang dapat ditinjau dalam satu waktu',
  'torrent.tree.summary': '{n} dari {total} berkas dipilih ({size})',
  'torrent.tree.private': 'Tracker privat',
  'torrent.tree.selectAll': 'Pilih semua',
  'torrent.tree.selectNone': 'Batalkan semua pilihan',
  'torrent.tree.cancel': 'Batal',
  'torrent.tree.add': 'Tambahkan ke pengumpul',

  'settings.torrents.notApplied': 'Build ini belum menerapkan dua dari pengaturan di bawah. Batas unggah disimpan dan diperiksa, tapi mesin torrent tidak bisa menerapkannya pada unduhan yang sedang berjalan. DHT dan PEX juga tidak sampai ke torrent biasa: torrent itu melakukan seed dengan keduanya menyala, apa pun pengaturannya di sini. Torrent privat bekerja dengan cara lain, seperti dijelaskan oleh (i) di Penemuan peer.',
  'onboarding.step': 'Langkah {n} dari {total}',
  'onboarding.skip': 'Lewati',
  'onboarding.back': 'Kembali',
  'onboarding.next': 'Berikutnya',
  'onboarding.finish': 'Selesai',
  'onboarding.welcome.title': 'Selamat datang di KnightLoader',
  'onboarding.welcome.body': 'KnightLoader adalah pengelola unduhan self-hosted. Tempel atau jatuhkan tautan, lalu backend yang cocok mengambilnya: mesin bawaan untuk tautan berkas biasa, yt-dlp untuk halaman media, layanan debrid untuk hoster yang sudah kamu bayar, atau JDownloader headless untuk selebihnya. Tur singkat ini membahas satu pengaturan yang layak diperiksa sebelum kamu mulai.',
  'onboarding.welcome.langLabel': 'Bahasa antarmuka',
  'onboarding.folder.title': 'Ke mana file harus disimpan?',
  'onboarding.folder.body': 'Ini folder tempat unduhan yang selesai ditulis. Ketik jalur atau jelajahi server untuk memilihnya. Kamu bisa mengubahnya lagi kapan saja dari halaman pengaturan Umum.',
  'onboarding.accounts.title': 'Hoster premium, kapan pun Anda mau',
  'onboarding.accounts.body': 'Antrean berjalan tanpa akun sama sekali. Kalau kamu ingin kecepatan penuh di hoster atau layanan debrid yang sudah kamu bayar, tambahkan login-nya di Akun. Semua ini tidak perlu diatur sekarang.',
  'onboarding.accounts.link': 'Buka Akun',
  'onboarding.finished.title': 'Anda siap',
  'onboarding.finished.body': 'Itulah akhir dari tur ini. Halaman Bantuan di bawah Pengaturan berisi penjelasan lengkap tentang semua hal lain yang dilakukan versi ini, dan sebagian besar kontrol memiliki penjelasannya sendiri di balik ikon (i).',

