  'settings.headerProfiles.title': 'Profil header',
  'settings.headerProfiles.hint': 'Sebagian situs hanya menyerahkan berkas kepada peramban yang sudah masuk, atau kepada permintaan yang datang dari salah satu halaman mereka sendiri. Sebuah profil menyimpan header untuk tepat satu situs, tersegel sama seperti kunci akunmu, dan KnightLoader mengirimkannya bersama setiap unduhan dari situs itu.',
