  'settings.rules.action.category': 'Kategori',
  'settings.rules.action.categoryHint': 'Menyimpan tautan yang cocok ke salah satu laci dari daftar Kategori di bagian bawah halaman ini, yang membawa foldernya sendiri, posisinya di antrean, sakelar ekstraksinya, dan aturannya untuk berkas yang sudah ada. Dibiarkan tidak diubah, tidak ada aturan yang berpendapat soal itu dan tautannya tetap tanpa kategori. Kalau aturan ini juga menyebut folder unduhan, folder itu yang menang, dan lacinya tetap menyumbang semua sisanya. Menyebut laci yang sudah dihapus ditolak saat kamu menyimpan, sebab aturan yang menunjuk ke laci yang tidak ada sama sekali tidak melakukan apa pun pada setiap tautan yang cocok dengannya, tanpa satu pun pesan.',
  'settings.rules.action.categoryNone': 'Belum ada kategori. Buat dulu satu di Kategori di bagian bawah halaman ini, kalau tidak, aturan ini akan menyimpan tautan ke laci yang tidak ada.',
