  'detail.messageHint': 'Kalimat dari apa pun yang mencoba mengambil ini, kata demi kata dan tanpa diterjemahkan. Itu adalah kegagalan yang sekarang dan bukan yang lain: mulai ulang menghapusnya, dan yang sebelumnya tidak disimpan di mana pun.',
  'detail.heldBack': 'Ditahan oleh',
  'detail.doing': 'Sedang melakukan',
  'detail.gaveUp': 'Tidak dicoba lagi',
  'detail.gaveUpHint': 'Yang ini berhenti dengan sengaja, bukan karena percobaannya habis: sebuah captcha, disk yang penuh, atau aturan yang mengatakan “jangan pernah” untuk hoster ini. Menaikkan jumlah percobaan ulang tidak mengubah apa pun di sini. Tandanya sendiri tidak ditulis ke basis data, jadi ia hilang setelah mulai ulang, meski alasannya tidak.',
  'detail.rules': 'Aturan yang membentuk ini',
  'detail.rulesHint': 'Aturan yang berjalan pada tautan ini saat ia disiapkan, dalam urutan jalannya. Aturan disimpan menurut namanya, jadi aturan yang sejak itu diganti namanya tidak ditemukan lagi, dan aturan yang tidak pernah punya nama disimpan menurut posisi yang dimilikinya saat itu. Mengekliknya membuka aturan itu di editor aturan.',
