  'notifications.event.extractionDoneHint': 'Arsip yang selesai diekstrak. Ini belum pernah dilaporkan di mana pun, jadi awalnya ia berdiri di “Jangan tampilkan apa pun”.',
  'notifications.event.extractionFailed': 'Ekstraksi gagal',
  'notifications.event.extractionFailedHint': 'Arsip yang berhenti tanpa selesai. Biasanya karena kata sandinya tidak ada, dan berkasnya tetap di tempatnya sampai kamu mengurusnya.',
  'notifications.event.captchaWaiting': 'Ada captcha yang menunggu',
  'notifications.event.captchaWaitingHint': 'Jendela captcha tetap terbuka di tab ini bagaimanapun juga. Awalnya ia berdiri di “Jangan tampilkan apa pun”, sebab jendela itu sudah menjadi pesannya selama kamu melihatnya. Setel ke notifikasi sistem, maka captcha di tab latar pun sampai kepadamu sebelum hosternya membuang sesinya.',
  'notifications.event.captchaFailed': 'Captcha gagal',
  'notifications.event.captchaFailedHint': 'Tidak ada yang menjawab tepat waktu, atau jawabannya tidak sampai. Unduhan di baliknya tetap di tempatnya.',
  'notifications.event.captchaResolved': 'Captcha dijawab di tempat lain',
  'notifications.event.captchaResolvedHint': 'Seseorang di peramban lain, atau pemecah otomatis, sudah menjawabnya, dan jendelanya menutup dengan sendirinya.',
  'notifications.systemUnavailable': 'Notifikasi sistem tidak tersedia di sini: peramban hanya menawarkannya lewat HTTPS atau di localhost. Semua yang ada di kartu ini tetap ditampilkan di dalam aplikasi.',
  'notifications.systemBlocked': 'Peramban memblokir notifikasi untuk alamat ini. Baris yang disetel ke “Notifikasi sistem” ditampilkan di dalam aplikasi sebagai gantinya, sampai kamu mengizinkannya lagi di pengaturan situs peramban.',
  'notifications.systemNotGranted': 'Peramban tidak memberi izin, jadi peristiwa ini tetap di dalam aplikasi. Pilih “Notifikasi sistem” sekali lagi untuk bertanya ulang.',
