  'settings.health.nothingWaiting': 'Tidak ada yang ditahan.',
  'settings.health.nothingFailed': 'Tidak ada di daftar yang gagal.',
  'settings.health.scrapeHint': 'Membuka alamat kedua yang memberikan angka yang sama sebagai teks biasa, dalam format yang dibaca Prometheus dan perkakas yang dibangun seperti itu. Ia diambil, tidak pernah dikirim: tidak ada yang meninggalkan mesin ini selama pemantauanmu sendiri tidak datang ke sini dan memintanya. Selama ini mati, alamatnya sama sekali tidak ada dan menjawab 404, sama seperti alamat mana pun yang tidak dipunyai aplikasi ini. Pada instans dengan kata sandi, pengambilannya butuh salah satu token APImu, dan setiap kolektor bisa diajari mengirimkan satu. Kolektor tidak mengirim header asal dan karena itu ia lolos; tab peramban di alamat lain memang mengirim satu dan ditolak kalau tidak cocok dengan alamat instans ini sendiri. Teksnya membawa jalur folder tujuanmu, jadi berikan ia hanya ke tempat yang juga akan kamu beri nama foldernya sendiri.',
  'settings.health.scrapeUrl': 'Alamat metrik',
  'settings.health.scrapeCopy': 'Salin alamat',
  'settings.health.scrapeCopied': 'Alamat disalin',
  'settings.health.scrapeOffHint': 'Alamat ini tidak menjawab apa pun selama sakelar di atas mati.',
  'settings.diagnostics.systemTitle': 'Informasi sistem',
  'settings.diagnostics.fileTitle': 'Berkas log',
  'settings.diagnostics.fileOn': 'Tulis log ke sebuah berkas',
  'settings.diagnostics.fileOnHint': 'Mati sampai kamu menyalakannya, dan pembaruan tidak pernah menyalakannya untukmu. Dengan ini menyala, instans ini menulis setiap baris yang dicatatnya ke sebuah berkas di folder datanya, supaya kerusakan dari dua malam lalu masih bisa dibaca setelah mulai ulang. Sebuah baris log bisa menyebut alamat feed yang kamu langgan, jadi perlakukan berkasnya sebagai milikmu. Di dalam kontainer, baris yang sama sudah sampai ke docker logs; berkasnya adalah apa yang tinggal setelah itu berlalu.',
  'settings.diagnostics.fileSize': 'Ukuran per berkas',
  'settings.diagnostics.fileSizeHint': 'Begitu berkasnya mencapai ukuran ini, ia diganti nama dan yang baru dimulai.',
  'settings.diagnostics.fileKeep': 'Berkas lama yang disimpan',
  'settings.diagnostics.fileKeepHint': 'Berapa banyak berkas yang sudah diganti namanya tetap tinggal di samping berkas yang sedang ditulis. Nol hanya menyimpan berkas yang sekarang; itu tidak mematikan log.',
  'settings.diagnostics.fileWhere': 'Di mana ia ditulis',
  'settings.diagnostics.fileWhereHint': 'Sudah ditetapkan, supaya salah ketik pada sebuah jalur tidak bisa menjadi penyebab lognya berhenti ditulis. Setel KL_LOG_DIR sebelum aplikasinya dimulai untuk menaruhnya di disk lain.',
  'settings.diagnostics.fileStateOff': 'Tidak sedang ditulis',
