  'settings.diagnostics.fileProblemHint': 'Periksa apakah {path} ada dan apakah akun yang menjalankan proses ini boleh menulis di sana. Di Unraid itu biasanya berarti foldernya milik root sementara kontainernya berjalan sebagai pengguna lain. Selebihnya tidak ada yang berhenti: {n} baris terakhir masih ada di memori dan tetap masuk ke paket diagnostik.',
  'settings.diagnostics.fileProblemSpace': 'Sisa {free} di volume itu.',
  'settings.diagnostics.fileProblemSpaceUnknown': 'Berapa ruang yang tersisa di volume itu tidak dapat dibaca pada sistem ini.',
  'settings.diagnostics.fileCurrent': 'Berkas yang berjalan',
