  'settings.diagnostics.fileEmpty': 'Belum ada yang ditulis.',
  'settings.diagnostics.fileDownload': 'Unduh',
  'settings.diagnostics.logSearch': 'Cari di barisnya',
  'settings.diagnostics.logSearchHint': 'Teks biasa, tanpa wildcard, huruf besar dan kecil diperlakukan sama. Ia mencari di baris yang dimuat di sini, bukan di berkas yang lebih lama. Unduh sebuah berkas untuk mencari di seluruh isinya.',
  'settings.diagnostics.logSource': 'Sumber',
