  'settings.diagnostics.logSourceOther': 'Baris selebihnya',
  'settings.diagnostics.logSourceHint': 'Dari bagian aplikasi mana sebuah baris berasal, dibaca dari awal barisnya sendiri. Baris yang tidak menyebut bagian mana pun ada di bawah "Baris selebihnya". Tidak ada tingkat keparahan untuk disaring: tidak ada satu pun di aplikasi ini yang mencatatnya.',
  'settings.diagnostics.logFollow': 'Ikuti baris baru',
  'settings.diagnostics.logFollowHint': 'Menanyakan setiap dua detik apa yang datang sejak terakhir kali dan melompat ke baris terbaru. Kalau dimatikan, tampilannya tetap di tempatnya, jadi kamu bisa membaca sesuatu tanpa ia tergeser pergi.',
