  'settings.diagnostics.logGap': '{n} baris terjatuh di antara dua kali pemeriksaan: yang datang lebih banyak daripada {cap} baris yang muat di memori. Nyalakan berkas log supaya semuanya tersimpan.',
  'settings.diagnostics.logTaskOnly': 'Hanya unduhan ini',
