  'settings.owner.identityTitle': 'Sebagai siapa instans ini menulis',
  'settings.owner.identityHint': 'Setiap berkas yang dibuat instans ini mendapat pemilik dan hak akses ini, dan semua yang ia jalankan juga begitu: yt-dlp, ffmpeg, dan JDownloader yang disertakan. Di dalam kontainer identitasnya sudah tetap begitu kontainernya dimulai, ditentukan oleh akun yang menjalankannya, dan tidak ada di halaman ini yang bisa mengubahnya.',
  'settings.owner.uid': 'Pengguna',
  'settings.owner.gid': 'Grup',
  'settings.owner.umask': 'Umask',
  'settings.owner.umaskUnknown': 'Kernel ini tidak melaporkannya',
  'settings.owner.asked': 'Yang diminta',
  'settings.owner.envIgnored': '{name}={value} disetel, tapi tidak ada satu pun di dalam image ini yang membacanya. Identitasnya ditentukan oleh akun yang dipakai saat kontainernya dijalankan, dan itu adalah {owner}.',
  'settings.owner.envHow': 'Kalau kamu mau berjalan di bawah akun lain, sebutkan akunnya di perintah start: --user <uid>:<gid>. Di Unraid itu masuk ke Extra Parameters, dan kontainernya harus dibuat ulang supaya berlaku.',
  'settings.owner.desktopNote': 'Aplikasi desktop berjalan di bawah akunmu sendiri. PUID, PGID, dan UMASK adalah pengaturan kontainer dan tidak berpengaruh apa-apa di sini.',
  'settings.owner.noOwners': 'Di sistem ini berkas tidak punya pemilik, jadi tidak ada yang bisa dibandingkan. Itu bukan kesalahan.',
  'settings.owner.checkTitle': 'Pemeriksaan folder',
  'settings.owner.checkHint': 'Di sini benar-benar satu berkas dan satu subfolder ditulis ke setiap folder, lalu dilihat siapa pemilik keduanya dan siapa lagi yang boleh membacanya, dan keduanya dihapus kembali. Ini harus diukur dan tidak boleh dihitung di atas kertas: folder berbagi bisa membawa aturan hak aksesnya sendiri, dan folder yang bertanda set-group-id memberikan grup yang lain daripada yang dipunyai proses ini. Pemeriksaannya berjalan dengan sendirinya setelah kamu menyimpan folder yang berubah, dan setiap kali kamu menekan tombolnya.',
  'settings.owner.run': 'Periksa foldernya sekarang',
  'settings.owner.running': 'Sedang diperiksa…',
  'settings.owner.never': 'Belum diperiksa.',
  'settings.owner.checkedAt': 'Terakhir diperiksa {time}.',
  'settings.owner.checkFailed': 'Pemeriksaannya tidak berjalan: {error}',
  'settings.owner.role.downloads': 'Folder unduhan',
