  'settings.owner.role.watch': 'Folder pantauan',
  'settings.owner.v.ok': 'Berkas mendarat di sini sebagai {fileOwner} dengan {fileMode}, subfolder baru dengan {subdirMode}, dan foldernya sendiri milik {dirOwner}. Tidak ada yang mencolok dari itu.',
  'settings.owner.v.ownerMismatch': 'Berkas mendarat di sini sebagai {fileOwner}, tapi foldernya milik {dirOwner}. Membacanya biasanya masih bisa; mengganti nama, memindahkan, dan menghapusnya dari akun lain tidak, dan apa pun yang mengharap sebuah folder memiliki isinya sendiri akan menganggap berkas itu asing.',
  'settings.owner.v.groupUnreadable': 'Berkas mendarat di sini dengan {fileMode}, jadi hanya {fileOwner} yang bisa membukanya. Apa pun yang berjalan di bawah akun lain melihat namanya dan tidak mendapat apa-apa lagi.',
  'settings.owner.v.dirUnreadable': 'Subfolder baru mendarat di sini dengan {subdirMode}. Selain {fileOwner} tidak ada yang bisa masuk ke dalamnya, apa pun yang diizinkan berkas di dalamnya, dan setiap unduhan mendarat di folder seperti itu.',
  'settings.owner.v.notWritable': 'Instans ini sama sekali tidak bisa menulis di sini: {detail}',
  'settings.owner.v.missing': 'Foldernya tidak ada. Ia akan dibuat pertama kali ada yang ditulis ke dalamnya.',
  'settings.owner.v.unknown': 'Di sistem ini berkas tidak punya pemilik, jadi di sini tidak ada yang bisa dibandingkan. Itu bukan kesalahan.',
  'settings.owner.fix.user': 'Jalankan kontainernya di bawah akun yang memiliki foldernya: --user {dirUid}:{dirGid} di perintah start. Di Unraid itu masuk ke Extra Parameters.',
  'settings.owner.fix.chown': 'Atau serahkan saja foldernya, di host: chown -R {uid}:{gid} {dir}',
  'settings.owner.fix.mask': 'Instans ini tidak bisa mengubahnya. Maskernya datang dari apa pun yang menjalankan kontainernya, dan folder berbagi yang dipasang bisa memaksakan maskernya sendiri lewat opsi umask, file_mode, atau dir_mode. Betulkan itu di tempat foldernya dipasang.',
  'settings.owner.fix.recreate': 'Perintah start yang berubah butuh kontainer yang dibuat ulang. Mulai ulang saja tidak cukup: identitasnya sudah tetap begitu ia dimulai.',
  'settings.owner.fix.past': 'Berkas yang sudah diunduh mempertahankan pemilik yang dipakai saat ia ditulis. Apa yang kamu ubah berlaku untuk semua yang baru; sisanya butuh perintah di atas.',
