  'settings.selftest.jd.missingAdvice': 'Build ini biasanya menjalankan JDownloader tanpa antarmukanya sendiri saat menyala dan mengisi KL_JD sendiri. Kalau isinya kosong, artinya start itu gagal. Cari "JD provisioning failed" di log lebih jauh ke bawah, atau setel KL_JD ke JDownloader milikmu sendiri.',
