  'settings.selftest.folders.notWritable': '{dir} tidak bisa ditulisi.',
  'settings.selftest.folders.notWritableAdvice': 'Proses ini berjalan sebagai uid {uid}. Lihat siapa pemilik folder itu di host dan apakah uid itu boleh menulis di dalamnya.',
  'settings.selftest.folders.missing': '{dir} belum ada, jadi angkanya menggambarkan {measured}.',
