  'settings.selftest.folders.low': 'Hanya sisa {free} di {dir}, di bawah {mark} yang membuat antrean berhenti.',
  'settings.selftest.folders.noMark': 'Sisa {free} di {dir}. Kamu belum menetapkan ambang tetap, jadi antrean hanya menahan unduhan yang memang sudah tidak muat apa adanya.',
