  'settings.resolvers.toolsSame': '{version} terpasang, dan itu adalah rilis terbaru yang diterbitkan.',
  'settings.resolvers.toolsNewer': 'Yang diterbitkan adalah {latest}, yang terpasang adalah {current}.',
  'settings.resolvers.toolsOlder': 'Yang terpasang adalah {current}, dan itu lebih baru daripada rilis terbaru yang diterbitkan ({latest}). Tidak ada yang perlu dikerjakan.',
  'settings.resolvers.toolsUnknown': 'Yang diterbitkan adalah {latest}, yang terpasang adalah {current}. Mana dari keduanya yang lebih baru tidak bisa dibaca dari dua keterangan versi itu, jadi di sini tidak ada yang dinyatakan.',
  'settings.resolvers.toolsCheckFailed': 'GitHub tidak bisa ditanyai: {error}',
