  'auth.passkey.title': 'Kunci sandi',
  'auth.passkey.hint': 'Kunci yang disimpan ponsel, laptop atau kunci keamananmu memasukkanmu tanpa mengetik kata sandi. Ini jalan masuk tambahan: kata sandi tetap berlaku, dan menghapus semua kunci sandi tidak mengunci siapa pun di luar. Sebuah kunci sandi milik alamat web tempat ia dibuat, jadi yang didaftarkan lewat proxy tidak berfungsi lewat alamat jaringan lokal, dan sebaliknya.',
  'auth.passkey.registered': '{n} terdaftar',
  'auth.passkey.none': 'Belum ada yang terdaftar',
  'auth.passkey.needsPassword': 'Setel kata sandi dulu. Kunci sandi adalah jalan kedua menuju sebuah login, jadi harus ada satu.',
  'auth.passkey.unavailableTitle': 'Kunci sandi butuh nama host, dan halaman ini dibuka pada alamat IP.',
  'auth.passkey.unavailableReason': 'Kunci sandi terikat pada sebuah domain, jadi peramban menolak seluruh pertukaran pada alamat telanjang, dan menolaknya lagi pada sertifikat yang tidak dipercaya. Capai KnightLoader lewat proxy terbalik dengan nama sungguhan dan sertifikat yang sah, buka di sana, lalu daftarkan kuncinya pada alamat itu.',
  'auth.passkey.noBrowserTitle': 'Peramban ini tidak menawarkan kunci sandi.',
  'auth.passkey.noBrowserReason': 'Tidak ada yang salah dengan instansi ini. Buka di peramban terkini, atau di perangkat yang bisa menyimpan kunci sandi, dan tombolnya muncul di sini.',
