  'auth.passkey.error.expired': 'Penyiapannya terlalu lama. Mulai lagi.',
  'auth.passkey.error.otherAddress': 'Penyiapan ini dimulai di alamat lain. Buka KnightLoader di alamat tempat kunci ini akan dipakai, lalu mulai lagi di sana.',
  'settings.stall.reconnect': 'Buka koneksi baru untuk unduhan yang macet',
  'settings.stall.reconnectHint': 'Menutup koneksi unduhan yang ditandai dan membuka koneksi baru yang meminta sisa berkas. Unduhan menyimpan apa yang sudah didapat dan tempatnya, karena itu ini aktif sampai Anda mematikannya. Server yang hanya bisa mengirim berkas utuh mengirimnya lagi dari awal. Tanpa ini, unduhan yang servernya berhenti menjawab di tengah berkas diam di 0 B/s sampai ada yang menjedanya. Selama unduhan diam, ini terulang setiap kali waktu yang diatur di atas habis. Jika “Mulai ulang unduhan yang macet” juga aktif, unduhan yang masih diam selama itu setelah koneksi baru dimulai dari awal. Hanya unduhan mesin bawaan yang mendapat koneksi baru, termasuk debrid dan TorBox. JDownloader dan yt-dlp mengurus koneksinya sendiri, dan koneksi baru tidak membantu torrent tanpa peer, jadi itu hanya ditandai.',
  'props.backend': 'Layanan',
  'props.backendAuto': 'Otomatis',
  'props.backendHint':
    'Which backend fetches these links. Automatic takes the first one in the priority order on the Accounts page that can take the link right now. A pinned link goes only to that backend, and fails with the reason when the backend cannot take it. A running download keeps its backend. A paused one moves when you resume it, and starts from the beginning there.',
