  'rename.torrent': 'Torrent menamai berkasnya sendiri, jadi namanya tidak bisa diganti.',
  'rename.volume': 'Berkas ini adalah satu bagian dari arsip berjilid banyak. Bagian-bagiannya mempertahankan nama, kalau tidak arsip tidak bisa diekstrak.',
  'rename.separator': 'Nama tidak boleh berisi / atau \\.',
