    'KnightLoader reads the service\'s list once a minute and brings in whatever was added there since you switched this on: torrents, and from TorBox and Premiumize.me also web and Usenet downloads. They land in the link collector like any other link and are fetched from this account. Nothing KnightLoader added itself comes in. The service does not say who added a download, so whatever another app adds with the same account comes in as well. Leave this off for an account that rdt-client or a second KnightLoader also uses. A download is deleted on the service once its files are here, or when you remove it here, unless "Keep downloads on the debrid service" is switched on under Settings, Torrents. A dash means the service has no list KnightLoader can read.',
